using namespace std;

int H, W; 
char s[1009][1009], t[3][3], x[4] = "JOI";

int main() {
    cin >> H >> W;
    for (int i = 0; i < H; i++) cin >> s[i];

    cin >> t[0] >> t[1];

    int sum = 0;
    for (int i = 0; i < H - 1; i++) {
        for (int j = 0; j < W - 1; j++) {
            if (s[i][j] == t[0][0] && s[i][j + 1] == t[0][1] && s[i + 1][j] == t[1][0] && s[i + 1][j + 1] == t[1][1]) {
                sum++;
            }
        }
    }

    int ret = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            char e = s[i][j];
            int a[3] = {0}, z = -1;
            for (int c = 0; c < 3; c++) {
                if (x[c] == e) z = c;
                s[i][j] = x[c];

                // Reduced nested loops by checking only valid ranges
                for (int k = 0; k + i + 1 < H; k++) {
                    for (int l = 0; l + j + 1 < W; l++) {
                        bool flag = (s[i + k][j] == t[0][0] && s[i + k][j + 1] == t[0][1] && 
                                     s[i + k + 1][j] == t[1][0] && s[i + k + 1][j + 1] == t[1][1]);
                        if (flag) a[c]++;
                    }
                }
            }
            for (int c = 0; c < 3; c++) ret = max(ret, sum + a[c] - a[z]);
            s[i][j] = e;
        }
    }

    cout << ret << endl;
    return 0;
}

